using Gauge;
using Gauge.Serialization.Json;
using InvoiceManagement.Library.DataAccess;
using InvoiceManagement.Library.Models;
using InvoiceManagement.Library.Services;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using static Gauge.DataGenerator.EnumHelper;

namespace InvoiceManagement.Tests.Integration.Scenarios.CreateInvoice
{
    public class CreateInvoiceScenarioDefinition : ScenarioDefinition
    {
        private HttpClient _httpClient;
        private OracleEbsDbConnection _dbConnection;

        public override Task TearDownCore()
        {
            _dbConnection?.Dispose();

            return Task.CompletedTask;
        }

        public CreateInvoiceScenarioDefinition(ScenarioId scenarioId, ScenarioContexts scenarioContexts) : base(scenarioId, scenarioContexts)
        {
            _httpClient = scenarioContexts["HttpClient"].Cast<HttpClient>().Single();
            var authService = scenarioContexts["AuthService"].Cast<AuthService>().Single();
            var userData = GetGaugeData<string>(PathsUserData.ApiToken);
            var userId = authService.GetUserId(userData);

            var dbConnectionString = GetGaugeData<string>(PathsEnvironment.DbConnectionString);
            _dbConnection = new OracleEbsDbConnection(dbConnectionString)
            {
                UserID = userId
            };
            _dbConnection.Open();
        }

        [Given(@"I have an invoice with valid payload:")]
        public async Task GivenIHaveAnInvoiceWithValidPayload(GaugeData payload)
        {
            var data = JsonConvert.DeserializeObject<CreateInvoiceRequest>(payload.Text);

            var invoice = DataFaker.Generate<CreateInvoiceRequest>()
                .With(x => x.CustomerName, data.CustomerName)
                .With(x => x.Items, data.Items);

            await _httpClient.PostAsync("/invoices", new StringContent(JsonConvert.SerializeObject(invoice), System.Text.Encoding.UTF8, "application/json"));
        }

        [Then(@"the HTTP response status code should be (.*策0)")]
        public async Task ThenTheHttpServletResponseStatusCodeShouldBe(int expectedStatusCode)
        {
            var response = await _httpClient.SendAsync(HttpMethod.Get, "/invoices/" + _responseId);

            var actualStatusCode = (int)response.StatusCode;

            Assert.That(actualStatusCode, Is.EqualTo(expectedStatusCode));
            _responseId = Guid.NewGuid().ToString();
        }

        [Then(@"the Oracle EBS database should have a new invoice record with:")]
        public Table ThenTheOracleEbsDatabaseShouldHaveANewInvoiceRecordWith(Table table)
        {
            var actualData = _dbConnection.ExecuteReader("SELECT customer_name, items.name, items.quantity, items.price FROM hr_invoices WHERE invoice_id = (SELECT MAX(invoice_id) FROM hr_invoices)", commandType: System.Data.CommandType.Text)
                .ToList()
                .Select(row => row.ItemArray)
                .Select(cl => cl.Cast<string>())
                .ToList()
                .AsTable();

            Assert.That(actualData, Is.EqualTo(table));

            return actualData;
        }
    }
}
```

